using BusinessPartnerPortal.Api.Common;using BusinessPartnerPortal.Api.Data;using BusinessPartnerPortal.Api.Security;using Microsoft.EntityFrameworkCore;
namespace BusinessPartnerPortal.Api.Features.VendorAccess;
public static class VendorAccessEndpoints{public static IEndpointRouteBuilder MapVendorAccessEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/v1/vendor-access").RequireAuthorization().WithTags("Vendor Access");g.MapGet("/",async(CurrentUser current,AppDbContext db,CancellationToken ct)=>{await current.DemandAsync("VENDOR.MANAGE",ct);var q=from vu in db.VendorUsers join u in db.Users on vu.UserId equals u.Id join v in db.Vendors on vu.VendorId equals v.Id orderby v.VendorName,u.FullName select new{userId=u.Id,u.FullName,u.Email,u.IsActive,vendorId=v.Id,v.VendorCode,v.VendorName,v.OracleVendorId,accessActive=vu.IsActive};return Results.Ok(await q.ToListAsync(ct));});g.MapPut("/{userId:guid}/active",async(Guid userId,AccessRequest req,CurrentUser current,AppDbContext db,CancellationToken ct)=>{await current.DemandAsync("VENDOR.MANAGE",ct);var u=await db.Users.FirstOrDefaultAsync(x=>x.Id==userId,ct)??throw new ApiException(404,"User not found.");u.IsActive=req.IsActive;u.UpdatedAt=DateTimeOffset.UtcNow;var maps=await db.VendorUsers.Where(x=>x.UserId==userId).ToListAsync(ct);foreach(var x in maps)x.IsActive=req.IsActive;await db.SaveChangesAsync(ct);return Results.Ok(new{userId,isActive=req.IsActive});});return app;}public sealed record AccessRequest(bool IsActive);}
